from app.core.config import settings
async def resumo(db): return (await db.execute_sql("SELECT COUNT(DISTINCT programa_cod) quantidadeProgramas,COUNT(DISTINCT CONCAT(programa_cod,'-',acao_cod)) quantidadeAcoes,SUM(CASE WHEN is_total=1 THEN orcamentario_executado ELSE 0 END) valorExecutado,MAX(emitido_em) dataReferencia FROM dbo.sigplan_execucao_regionalizada_2026;",settings.sigplan_database))[0]
async def regioes(db): return await db.execute_sql("SELECT LTRIM(RTRIM(regiao)) regiao,SUM(orcamentario_executado) valorExecutado,SUM(orcamentario_programado_ppag) valorProgramado,COUNT(DISTINCT CONCAT(programa_cod,'-',acao_cod)) quantidadeAcoes FROM dbo.sigplan_execucao_regionalizada_2026 WHERE is_total=0 AND NULLIF(LTRIM(RTRIM(regiao)),'') IS NOT NULL GROUP BY LTRIM(RTRIM(regiao)) ORDER BY valorExecutado DESC;",settings.sigplan_database)
async def municipios(db): return await db.execute_sql("SELECT DISTINCT municipio_ibge_cod municipioIbgeCod,municipio,regiao_geografica_cod regiaoCod,LTRIM(RTRIM(regiao_geografica_desc)) regiao FROM dbo.localizadores_todos_planejamento WHERE municipio_ibge_cod IS NOT NULL AND regiao_geografica_desc IS NOT NULL AND is_deleted_localizador=0;",settings.sigplan_database)
async def ods(db): return await db.execute_sql("WITH e AS(SELECT programa_cod,SUM(orcamentario_executado) valor FROM dbo.sigplan_execucao_regionalizada_2026 WHERE is_total=1 GROUP BY programa_cod),o AS(SELECT DISTINCT programa_cod,LTRIM(RTRIM(ods_titulo)) titulo,NULLIF(LTRIM(RTRIM(ods_subtitulo)),'') subtitulo FROM dbo.programas_planejamento WHERE NULLIF(LTRIM(RTRIM(ods_titulo)),'') IS NOT NULL),q AS(SELECT programa_cod,COUNT(*) qtd FROM o GROUP BY programa_cod) SELECT o.titulo odsTitulo,MAX(o.subtitulo) odsSubtitulo,SUM(e.valor/NULLIF(q.qtd,0)) valorExecutado,COUNT(DISTINCT e.programa_cod) quantidadeProgramas FROM e JOIN o ON o.programa_cod=e.programa_cod JOIN q ON q.programa_cod=e.programa_cod GROUP BY o.titulo ORDER BY valorExecutado DESC;",settings.sigplan_database)
async def funcoes(db): return await db.execute_sql("SELECT COALESCE(a.funcao_desc,'Não informado') AS funcao,SUM(e.orcamentario_executado) AS valorExecutado,SUM(e.orcamentario_programado_ppag) AS valorProgramado FROM dbo.sigplan_execucao_regionalizada_2026 e LEFT JOIN dbo.acoes_planejamento a ON a.programa_cod=e.programa_cod AND a.acao_cod=e.acao_cod AND a.uo_acao_cod=e.uo_cod WHERE e.is_total=1 GROUP BY COALESCE(a.funcao_desc,'Não informado') ORDER BY valorExecutado DESC;",settings.sigplan_database)
async def uos(db): return await db.execute_sql("WITH execucao_programa AS(SELECT programa_cod,SUM(orcamentario_executado) AS valorExecutado FROM dbo.sigplan_execucao_regionalizada_2026 WHERE is_total=1 GROUP BY programa_cod),programa_uo AS(SELECT programa_cod,MAX(COALESCE(uo_programa_nome,'Não informado')) AS uo FROM dbo.programas_planejamento WHERE is_deleted_programa=0 GROUP BY programa_cod) SELECT pu.uo,SUM(ep.valorExecutado) AS valorExecutado,COUNT(DISTINCT ep.programa_cod) AS quantidadeProgramas FROM execucao_programa ep LEFT JOIN programa_uo pu ON pu.programa_cod=ep.programa_cod GROUP BY pu.uo ORDER BY valorExecutado DESC;",settings.sigplan_database)
async def populacao(client):
 r=await client.get(settings.ibge_population_url,headers={'Accept':'application/json'});r.raise_for_status();p=r.json();series=((p[0].get('resultados') or [{}])[0].get('series') or []) if p else []
 return [{'municipioIbgeCod':''.join(filter(str.isdigit,str(x.get('localidade',{}).get('id','')))),'municipio':x.get('localidade',{}).get('nome',''),'populacao':int(next(iter((x.get('serie') or {'x':0}).values()),0) or 0)} for x in series]
